return ['domain'=>'acfml','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sv_SE','project-id-version'=>'Advanced Custom Fields Multilingual 5.2.0','pot-creation-date'=>'2026-10-20 11:37+0000','po-revision-date'=>'2026-10-20 11:37+0000','x-generator'=>'PTC (Private Translation Cloud)','messages'=>['Advanced Custom Fields Multilingual'=>'Advanced Custom Fields Multilingual','https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/','Adds compatibility between WPML and Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Documentation</a>'=>'Gör WPML och Advanced Custom Fields kompatibla | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Dokumentation</a>','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Displayed when editing an ACF field in a translation, showing its value in the original language; %1$s and %2$s turn the string into bold, and %3$s is the actual original value.%1$sOriginal%2$s: %3$s'=>'%1$sOriginal%2$s: %3$s','This type of ACF field will always be set to "Copy once".'=>'Denna fälttyp kommer alltid att vara inställd på “Kopiera en gång”.','ACF field name:'=>'ACF-fältnamn:','ACF field type:'=>'ACF-fälttyp:','Translation preferences'=>'Översättningsval','What to do with field\'s value when post/page is going to be translated'=>'Vad som ska göras med fältets värde när inlägget/sidan ska översättas','Translate (your current setting, no longer offered for this field type)'=>'Översätt (ditt nuvarande val, erbjuds inte längre för denna fälttyp)','Kept because it is your current setting. This value is no longer offered for this field type.'=>'Behålls eftersom det är ditt nuvarande val. Detta värde erbjuds inte längre för denna fälttyp.','Not recommended for this field type.'=>'Rekommenderas inte för denna fälttyp.','Translated pages start without this content.'=>'Översatta sidor börjar utan detta innehåll.','Editable in other languages, and starts empty.'=>'Går att redigera på andra språk och börjar tom.','Visitors in every language always see exactly what the original shows.'=>'Besökare på alla språk ser alltid exakt det som originalet visar.','Shown locked in other languages, so it cannot be edited there.'=>'Visas som låst på andra språk, så det kan inte redigeras där.','Starts the same as the original, then each language goes its own way.'=>'Börjar likadant som originalet, sedan går varje språk sin egen väg.','Editable in every language, and permanently yours to maintain by hand.'=>'Går att redigera på alla språk och underhålls permanent manuellt av dig.','Visitors see this in their own language.'=>'Besökare ser detta på sitt eget språk.','Filled by the translation and edited in the translation editor.'=>'Fylls i av översättningen och redigeras i översättningsredigeraren.','Edit the field to set the translation preference.'=>'Redigera fältet för att ange översättningsval.','ACFML is updating translation preferences for strings in Gutenberg Blocks. Keep using your site as usual. This notice will disappear when the process is done.'=>'ACFML uppdaterar översättningsval för strängar i Gutenberg-block. Fortsätt använda din webbplats som vanligt. Detta meddelande försvinner när processen är klar.','ACFML is enabled but not effective. It requires WPML in order to work.'=>'ACFML är aktiverat men fungerar inte. Det kräver WPML för att fungera.','ACFML is enabled but not effective. It requires Advanced Custom Fields or ACF PRO in order to work.'=>'ACFML är aktiverat men fungerar inte. Det kräver Advanced Custom Fields eller ACF PRO för att fungera.','Activate Advanced Custom Fields'=>'Aktivera Advanced Custom Fields','Install Advanced Custom Fields'=>'Installera Advanced Custom Fields','Field groups are set to "Translatable" in WPML settings, which prevents ACF fields from being translated.'=>'Fältgrupper är inställda på “Översättningsbar” i WPML-inställningarna, vilket förhindrar att ACF-fält översätts.','This is almost never intended.'=>'Detta är nästan aldrig avsiktligt.','A configuration file (wpml-config.xml) controls this setting on this site, so it cannot be changed from here. Edit that file, or ask whoever maintains it to set the ACF field group post type to Not translatable.'=>'En konfigurationsfil (wpml-config.xml) styr denna inställning på webbplatsen, så den kan inte ändras härifrån. Redigera filen, eller be den som underhåller den att ställa in inläggstypen för ACF-fältgrupper till “Inte översättningsbar”.','Field group copies already created in other languages stay on the site. Changing this setting does not delete them.'=>'Kopior av fältgrupper som redan skapats på andra språk stannar kvar på webbplatsen. Att ändra denna inställning raderar dem inte.','Set field groups to Not translatable'=>'Ställ in fältgrupper till Inte översättningsbar','Why this matters'=>'Varför detta är viktigt','If any field is set to "Translatable", WPML will re-translate the %d posts using this field group.'=>'Om något fält är inställt på “Översätt”, kommer WPML att översätta om de %d inlägg som använder denna fältgrupp.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to 1 minute.'=>'Vissa inlägg som använder denna fältgrupp har översättningar. När du ändrar översättningsvalet behöver WPML uppdatera inläggens översättningsstatus. Detta kan ta upp till 1 minut.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d hours.'=>'Vissa inlägg som använder denna fältgrupp har översättningar. När du ändrar översättningsvalet behöver WPML uppdatera inläggens översättningsstatus. Detta kan ta upp till %d timmar.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d minutes.'=>'Vissa inlägg som använder denna fältgrupp har översättningar. När du ändrar översättningsvalet behöver WPML uppdatera inläggens översättningsstatus. Detta kan ta upp till %d minuter.','Locked by WPML so that ACF fields stay translatable. Click here to unlock and change it anyway.'=>'Låst av WPML så att ACF-fält förblir översättningsbara. Klicka här för att låsa upp och ändra det ändå.','Set translation preferences for the attached taxonomy'=>'Ange översättningsval för den kopplade taxonomin','Set translation preferences for the attached post type'=>'Ange översättningsval för den kopplade inläggstypen','If you want to translate your fields, go to the WPML Settings page and make the taxonomy attached to this field group translatable. '=>'Om du vill översätta dina fält, gå till sidan för WPML-inställningar och gör taxonomin som är kopplad till denna fältgrupp översättningsbar. ','If you want to translate your fields, go to the WPML Settings page and %1$smake the post type attached to this field group translatable%2$s.'=>'Om du vill översätta dina fält, gå till sidan för WPML-inställningar och %1$sgör inläggstypen som är kopplad till denna fältgrupp översättningsbar%2$s.','Expert'=>'Expert','Same content in every language, translated'=>'Samma innehåll på alla språk, översatt','Each language has its own content'=>'Varje språk har sitt eget innehåll','Translate is not offered on container fields, because it replaces the value your theme reads. The fields inside carry their own preferences.'=>'Översätt erbjuds inte för behållarfält, eftersom det ersätter värdet som ditt tema läser. Fälten inuti har sina egna inställningar.','Translate lets each language point at its own address, which an external link often needs. A link to a page on this site already points at that page in the reader\'s language, so leave it as it is.'=>'Översätt låter varje språk peka på sin egen adress, vilket en extern länk ofta behöver. En länk till en sida på den här webbplatsen pekar redan på den sidan på läsarens språk, så låt den vara som den är.','Translate sends the link text and the URL. The target keeps the value you set, and a URL you leave as it is points at the page in the reader\'s language.'=>'Översätt skickar länktexten och webbadressen. Målet behåller värdet du anger, och en webbadress som du lämnar som den är pekar på sidan på läsarens språk.','Translating an address produces one that does not exist. An e-mail address is the same in every language.'=>'Att översätta en adress skapar en som inte existerar. En e-postadress är densamma på alla språk.','A color code is not language content. Translating it changes the color your visitors see.'=>'En färgkod är inte språkinnehåll. Att översätta den ändrar färgen som dina besökare ser.','The stored value is a fixed date format that your theme reads. Translating it breaks the format.'=>'Det lagrade värdet är ett fast datumformat som ditt tema läser. Att översätta det förstör formatet.','The stored value is the choice key, not the label your visitors see. Translating it stops the key from matching your choices. Translate the labels in <b>String Translation</b> instead.'=>'Det lagrade värdet är valnyckeln, inte etiketten som dina besökare ser. Att översätta den gör att nyckeln inte längre matchar dina val. Översätt etiketterna i <b>Strängöversättning</b> istället.','This value is read by your theme or plugin code. A translated value can stop matching what the code expects.'=>'Detta värde läses av ditt tema eller din plugin-kod. Ett översatt värde kan sluta matcha vad koden förväntar sig.','The file decides this again on every import, so changes made elsewhere do not stick.'=>'Filen bestämmer detta på nytt vid varje import, så ändringar som görs på andra ställen sparas inte.','Edit %s, or remove the entry there, to manage this field on this screen.'=>'Redigera %s, eller ta bort posten där, för att hantera detta fält på denna skärm.','Edit the configuration file, or remove the entry there, to manage this field on this screen.'=>'Redigera konfigurationsfilen, eller ta bort posten där, för att hantera detta fält på denna skärm.','That is not the value selected above. Saving this field group applies the value above.'=>'Det är inte värdet som valts ovan. Genom att spara denna fältgrupp tillämpas värdet ovan.','This field group is also in %s. That file re-applies these settings the next time the group is synced.'=>'Denna fältgrupp finns också i %s. Den filen tillämpar dessa inställningar igen nästa gång gruppen synkroniseras.','Locked. Managed by your theme, in its wpml-config.xml file.'=>'Låst. Hanteras av ditt tema i dess wpml-config.xml-fil.','Locked. Managed by a plugin, in its wpml-config.xml file.'=>'Låst. Hanteras av ett plugin i dess wpml-config.xml-fil.','Locked. Managed by a configuration file WPML downloaded for one of your plugins or themes.'=>'Låst. Hanteras av en konfigurationsfil som WPML laddat ner för ett av dina teman eller plugins.','Locked. Managed by the custom XML configuration saved in WPML settings.'=>'Låst. Hanteras av den anpassade XML-konfigurationen som sparats i WPML-inställningarna.','Locked. Managed by a configuration file on this site.'=>'Låst. Hanteras av en konfigurationsfil på denna webbplats.','Set in the field group "%s", which uses the same field name.'=>'Inställt i fältgruppen “%s”, som använder samma fältnamn.','Set in the field group\'s local JSON file.'=>'Inställt i fältgruppens lokala JSON-fil.','Set in the field group\'s local JSON file, %s.'=>'Inställt i fältgruppens lokala JSON-fil, %s.','Registered with PHP by your theme or a plugin.'=>'Registrerat med PHP av ditt tema eller ett plugin.','Set on the WPML Settings screen (Custom Fields Translation).'=>'Inställt på skärmen för WPML-inställningar (Översättning av anpassade fält).','Set here, on this screen.'=>'Inställt här, på denna skärm.','Right now this field is translated, so visitors see it in their own language.'=>'Just nu är detta fält översatt, så besökare ser det på sitt eget språk.','Right now this field stays identical in every language.'=>'Just nu förblir detta fält identiskt på alla språk.','Right now this field starts as a copy in every language, then each language keeps its own.'=>'Just nu börjar detta fält som en kopia på alla språk, sedan behåller varje språk sitt eget.','Right now this field stays out of translations.'=>'Just nu lämnas detta fält utanför översättningar.','Don\'t translate'=>'Översätt inte','Copy'=>'Kopiera','Copy once'=>'Kopiera en gång','Translate'=>'Översätt','Field groups'=>'Fältgrupper','Fields'=>'Fält','Posts'=>'Inlägg','Review them one by one'=>'Granska dem var för sig','Apply the recommended setup to %d group'=>'Tillämpa den rekommenderade konfigurationen på %d grupp' . "\0" . 'Tillämpa den rekommenderade konfigurationen på alla %d','%d ACF field group is not configured for translation.'=>'%d ACF-fältgrupp är inte konfigurerad för översättning.' . "\0" . '%d ACF-fältgrupper är inte konfigurerade för översättning.','%d post'=>'%d inlägg' . "\0" . '%d inlägg','%1$s field, used on %2$s, would be skipped and stay in %3$s.'=>'%1$s fält, som används i %2$s, hoppas över och stannar på %3$s.' . "\0" . '%1$s fält, som används i %2$s, hoppas över och stannar på %3$s.','%1$s field, used on %2$s, would be skipped and stay untranslated.'=>'%1$s fält, som används i %2$s, hoppas över och förblir oöversatt.' . "\0" . '%1$s fält, som används i %2$s, hoppas över och förblir oöversatta.','You are not allowed to change the translation setup of ACF field groups.'=>'Du har inte behörighet att ändra konfigurationen för översättning av ACF-fältgrupper.','You are not allowed to change the WPML translation settings on this site.'=>'Du har inte behörighet att ändra WPML:s översättningsinställningar på denna webbplats.','To change the translation options for custom fields, edit the field group "%s".'=>'För att ändra översättningsvalen för anpassade fält, redigera fältgruppen “%s”.','These fields come from ACF’s Local JSON files. To change their translation options, go to ACF → Field Groups, sync them, and then edit their settings.'=>'Dessa fält kommer från ACF:s lokala JSON-filer. För att ändra deras översättningsval, gå till ACF → Fältgrupper, synkronisera dem och redigera sedan deras inställningar.','This field and its translation setting are registered via PHP by your theme or plugin. Changes made here will override the original configuration.'=>'Detta fält och dess översättningsinställning är registrerade via PHP av ditt tema eller plugin. Ändringar som görs här kommer att skriva över den ursprungliga konfigurationen.','ACF translation setup'=>'ACF-översättningskonfiguration','Translation setup'=>'Översättningskonfiguration','You are not allowed to review the translation setup of ACF field groups.'=>'Du har inte behörighet att granska konfigurationen för översättning av ACF-fältgrupper.','Field group'=>'Fältgrupp','Setup'=>'Konfiguration','Actions'=>'Åtgärder','This site has no ACF field groups yet.'=>'Denna webbplats har inga ACF-fältgrupper ännu.','Alert:'=>'Varning:','How to do that'=>'Hur man gör det','View fields'=>'Visa fält','Open Dashboard'=>'Översikt','Apply the recommended setup'=>'Tillämpa rekommenderad konfiguration','Every field group stored in this site’s database already has a translation setup.'=>'Varje fältgrupp som lagras i denna webbplats databas har redan en översättningskonfiguration.','Back to the field groups'=>'Tillbaka till fältgrupperna','Every field in those groups then gets the translation preference WPML recommends for its field type. A preference that was set by hand in one of them is replaced.'=>'Varje fält i dessa grupper får då det översättningsval som WPML rekommenderar för dess fälttyp. Ett val som ställts in manuellt i någon av dem ersätts.','Field groups that come from your theme, a plugin’s code, or an acf-json file are not changed. They cannot be saved from here.'=>'Fältgrupper som kommer från ditt tema, ett plugins kod eller en acf-json-fil ändras inte. De kan inte sparas härifrån.','Cancel'=>'Avbryt','%d field group.'=>'%d fältgrupp.' . "\0" . '%d fältgrupper.','All of them have a translation setup.'=>'Alla har en översättningskonfiguration.','%d is not configured.'=>'%d är inte konfigurerad.' . "\0" . '%d är inte konfigurerade.','Apply recommended setup to the %d unconfigured group'=>'Tillämpa rekommenderad konfiguration på den %d okonfigurerade gruppen' . "\0" . 'Tillämpa rekommenderad konfiguration på alla %d okonfigurerade grupper','This sets %1$d field group to “%2$s”.'=>'Detta ställer in %1$d fältgrupp till “%2$s”.' . "\0" . 'Det detta ställer in %1$d fältgrupper till “%2$s”.','%d field group is defined in code, so it cannot be configured from here.'=>'%d fältgrupp är definierad i kod, så den kan inte konfigureras härifrån.' . "\0" . '%d fältgrupper är definierade i kod, så de kan inte konfigureras härifrån.','Not configured'=>'Inte konfigurerad','Not configured (defined in code)'=>'Inte konfigurerad (definierad i kod)','Set for each field (defined in code)'=>'Inställt för varje fält (definierat i kod)','Set for each field in WPML Settings (defined in code)'=>'Anges för varje fält i WPML-inställningar (definierade i kod)','%d field set manually'=>'%d fält inställt manuellt' . "\0" . '%d fält inställda manuellt','Nothing decides how these fields are translated. Set %s on the fields in the code that registers this group.'=>'Ingenting bestämmer hur dessa fält översätts. Ange %s på fälten i koden som registrerar denna grupp.','from an acf-json file'=>'från en acf-json-fil','from an acf-json file that is newer than this site’s copy'=>'från en acf-json-fil som är nyare än webbplatsens kopia','from your theme or a plugin’s code'=>'från ditt tema eller ett plugins kod','%d field group now uses the recommended setup.'=>'%d fältgrupp använder nu den rekommenderade konfigurationen.' . "\0" . '%d fältgrupper använder nu den rekommenderade konfigurationen.','%d field group has a newer acf-json file waiting to be synced, so that file decides its setup.'=>'%d fältgrupp har en nyare acf-json-fil som väntar på att synkroniseras, så den filen bestämmer dess konfiguration.' . "\0" . '%d fältgrupper har en nyare acf-json-fil som väntar på att synkroniseras, så dessa filer bestämmer deras konfiguration.','Translation Option'=>'Översättningsval','Multilingual Setup'=>'Flerspråkig konfiguration','Loading...'=>'Laddar...','Activate <b>String Translation</b>'=>'Aktivera <b>strängöversättning</b>','To translate field group names and labels, please %1$sinstall and activate WPML’s String Translation add-on%2$s.'=>'För att översätta fältgruppsnamn och etiketter, vänligen %1$sinstallera och aktivera WPML:s tillägg String Translation%2$s.','Activate now'=>'Aktivera nu','Go back'=>'Gå tillbaka','Set Up <b>Field Group Translation</b>'=>'Konfigurera <b>översättning av fältgrupp</b>','To translate field labels from the <b>Translation Management</b> dashboard, finish the <b>Multilingual Setup</b> and save your field group settings.'=>'För att översätta fältetiketter från översikten för <b>Translation Management</b>, slutför <b>flerspråkig konfiguration</b> och spara dina fältgruppsinställningar.','OK'=>'OK','Translate Field Labels'=>'Översätt fältetiketter','To translate field labels, use the <b>Translation Management</b> dashboard.'=>'För att översätta fältetiketter, använd översikten för <b>Translation Management</b>.','Translate in <b>Translation Management</b>'=>'Översätt i <b>translation management</b>','Don’t want to translate field labels? %1$sLearn how to disable field label translation%2$s'=>'Vill du inte översätta fältetiketter? %1$sLär dig hur du inaktiverar översättning av fältetiketter%2$s','Field Labels Partly Translated'=>'Fältetiketter delvis översatta','Some field labels in this group are still untranslated. To finish translating them, go to the <b>Translation Management</b> dashboard.'=>'Vissa fältetiketter i denna grupp är fortfarande inte översatta. För att slutföra översättningen av dem, gå till översikten för <b>Translation Management</b>.','Fields Labels Already Translated'=>'Fältetiketter redan översatta','You already translated all field labels in this group. To update any translations, go to the <b>Translation Management</b> dashboard.'=>'Du har redan översatt alla fältetiketter i denna grupp. För att uppdatera översättningar, gå till översikten för <b>Translation Management</b>.','Go to <b>Translation Management</b>'=>'Gå till <b>translation management</b>','Select a translation option for this field group'=>'Välj ett översättningsval för denna fältgrupp','Visitors everywhere see the same pages, in their own language. Text is translated; layout and settings stay identical.'=>'Besökare överallt ser samma sidor, på sitt eget språk. Text översätts; layout och inställningar förblir identiska.','You translate in the WPML <b>Translation Editor</b>. This works with automatic translation and <b>Translate Everything</b>.'=>'Du översätter i WPML:s <b>översättningsredigerare</b>. Detta fungerar med automatisk översättning och <b>Translate Everything</b>.','Every language’s pages are written and maintained on their own. Fields start as a copy of the original, then go their own way.'=>'Varje språks sidor skrivs och underhålls var för sig. Fält börjar som en kopia av originalet och går sedan sin egen väg.','You edit each language in the WordPress editor. WPML does not sync them afterwards, and automatic translation does not apply.'=>'Du redigerar varje språk i WordPress-redigeraren. WPML synkroniserar dem inte efteråt, och automatisk översättning tillämpas inte.','If you are migrating a site, your existing field groups will use the Expert setup. This allows you to manually choose the translation option for each field in the group.'=>'Om du migrerar en webbplats kommer dina befintliga fältgrupper att använda Expert-konfigurationen. Detta gör att du manuellt kan välja översättningsval för varje fält i gruppen.','This option is %1$snot recommended%2$s for new field groups.'=>'Detta alternativ är %1$sinte rekommenderat%2$s för nya fältgrupper.','Expert setup documentation'=>'Dokumentation för Expert-konfiguration','Choose'=>'Välj','recommended for this site'=>'rekommenderas för denna webbplats','Change option'=>'Ändra val','A Much Simpler Way to Translate Your ACF Sites'=>'Ett mycket enklare sätt att översätta dina ACF-webbplatser','This new release of ACFML allows you to configure multilingual sites in one-click, instead of many complex settings. Choose how to setup the translation for the fields.'=>'Denna nya version av ACFML låter dig konfigurera flerspråkiga webbplatser med ett klick, istället för många komplexa inställningar. Välj hur översättningen för fälten ska konfigureras.','Go to WPML Settings'=>'Gå till WPML-inställningar','Need help choosing?'=>'Behöver du hjälp med att välja?','Documentation'=>'Dokumentation','How to translate field labels »'=>'Hur man översätter fältetiketter »','This setup translates field values.'=>'Denna konfiguration översätter fältvärden.','Translate field labels and dropdown choice labels separately. Find them under ACF Field Group in the <b>Translation Dashboard</b>.'=>'Översätt fältetiketter och etiketter för rullgardinsval separat. Du hittar dem under ACF Field Group i <b>översikten för översättning</b>.','Review these translation setting changes'=>'Granska dessa ändringar av översättningsinställningar','Saving this field group makes these changes:'=>'Genom att spara denna fältgrupp görs dessa ändringar:','%1$s: from “%2$s” to “%3$s”'=>'%1$s: från “%2$s” till “%3$s”','Switching to the field-by-field setup keeps every field\'s current setting. From here you set each field yourself.'=>'Genom att byta till fält-för-fält-konfiguration behålls varje fälts nuvarande inställning. Härifrån ställer du in varje fält själv.','New translations use the new settings automatically.'=>'Nya översättningar använder de nya inställningarna automatiskt.','Not set'=>'Inte angivet','No posts with translations use this field group yet, so nothing has to be sent again.'=>'Inga inlägg med översättningar använder denna fältgrupp ännu, så ingenting behöver skickas igen.','No terms with translations use this field group yet, so nothing has to be sent again.'=>'Inga termer med översättningar använder denna fältgrupp ännu, så ingenting behöver skickas igen.','No posts or terms with translations use this field group yet, so nothing has to be sent again.'=>'Inga inlägg eller termer med översättningar använder denna fältgrupp ännu, så ingenting behöver skickas igen.','Only apply to new translations'=>'Tillämpa endast på nya översättningar','Checking how much content this affects...'=>'Kontrollerar hur mycket innehåll detta påverkar...','Save changes'=>'Spara ändringar','No, go back'=>'Nej, gå tillbaka','Updating them sends them for translation again, which may use translation words.'=>'Att uppdatera dem skickar dem för översättning igen, vilket kan använda översättningsord.','Updating them marks their translations as needing an update. WPML does not send them for translation. You can send them from the Translation Dashboard.'=>'Att uppdatera dem markerar deras översättningar som i behov av uppdatering. WPML skickar dem inte för översättning. Du kan skicka dem från Translation Dashboard.','Switching the setup applies the recommended value to the %d field in this group.'=>'Att byta konfiguration tillämpar det rekommenderade värdet på %d fält i denna grupp.' . "\0" . 'Att byta konfiguration tillämpar det rekommenderade värdet på alla %d fält i denna grupp.','%d post already has translations that used the old settings.'=>'%d inlägg har redan översättningar som använde de gamla inställningarna.' . "\0" . '%d inlägg har redan översättningar som använde de gamla inställningarna.','%d term already has translations that used the old settings.'=>'%d term har redan översättningar som använde de gamla inställningarna.' . "\0" . '%d termer har redan översättningar som använde de gamla inställningarna.','%d post uses this field group.'=>'%d inlägg använder denna fältgrupp.' . "\0" . '%d inlägg använder denna fältgrupp.','%d post is translated by hand, so WPML does not send it for translation.'=>'%d inlägg översätts för hand, så WPML skickar det inte för översättning.' . "\0" . '%d inlägg översätts för hand, så WPML skickar dem inte för översättning.','Also update the %d existing post'=>'Uppdatera även det %d befintliga inlägget' . "\0" . 'Uppdatera även de %d befintliga inläggen','Also update the %d existing term'=>'Uppdatera även den %d befintliga termen' . "\0" . 'Uppdatera även de %d befintliga termerna','Also update the %1$d existing posts and %2$d terms'=>'Uppdatera även de %1$d befintliga inläggen och %2$d termerna','Also update the %1$d existing post and %2$d terms'=>'Uppdatera även det %1$d befintliga inlägget och %2$d termerna','Also update the %1$d existing posts and %2$d term'=>'Uppdatera även de %1$d befintliga inläggen och %2$d termen','Also update the %1$d existing post and %2$d term'=>'Uppdatera även det %1$d befintliga inlägget och %2$d termen','This field group is shown on an Options page.'=>'Denna fältgrupp visas på en alternativsida.','That is usually site-wide content like your header, footer, or global blocks.'=>'Det är vanligtvis innehåll som omfattar hela webbplatsen, som ditt sidhuvud, din sidfot eller globala block.','To translate that content, use the %1$sWPML Translation Dashboard%2$s.'=>'För att översätta det innehållet, använd %1$sWPML:s översikt för översättning%2$s.','The options below still decide how each field behaves: translated, copied to every language, or kept separately per language.'=>'Alternativen nedan avgör fortfarande hur varje fält beter sig: översatt, kopierat till varje språk eller hanterat separat per språk.','This field group also appears on an Options page.'=>'Denna fältgrupp visas även på en alternativsida.','That content is translated in the %1$sWPML Translation Dashboard%2$s, and the option you choose here decides how each of its fields behaves.'=>'Det innehållet översätts i %1$sWPML:s översikt för översättning%2$s, och alternativet du väljer här avgör hur vart och ett av dess fält beter sig.','Post Type Translation'=>'Översättning av inläggstyper','Labels Translation'=>'Översättning av etiketter','Taxonomy Translation'=>'Översättning av taxonomier','Finish the ACF <b>Multilingual Setup</b>'=>'Slutför ACF:s <b>multispråkiga konfiguration</b>','Before you can start translating, you need to edit each ACF Field Group to set a translation option for the fields inside it.'=>'Innan du kan börja översätta måste du redigera varje ACF-fältgrupp för att ange ett översättningsval för fälten i den.','Read more about %1$show to translate your ACF custom fields%2$s'=>'Läs mer om %1$shur du översätter dina anpassade ACF-fält%2$s','%1$sSet translation options%2$s'=>'%1$sAnge översättningsval%2$s','Let\'s Start Translating!'=>'Låt oss börja översätta!','Edit each Field Group to select a translation option for the fields inside it. If you don\'t set a translation option, you will not be able to translate your fields.'=>'Redigera varje fältgrupp för att välja ett översättningsval för fälten i den. Om du inte anger ett översättningsval kommer du inte att kunna översätta dina fält.','A field in "%s" has the same name as a field in another field group. WPML stores translation preferences by field name, so two fields that share a name cannot be set differently.'=>'Ett fält i “%s” har samma namn som ett fält i en annan fältgrupp. WPML sparar översättningsval per fältnamn, så två fält som delar namn kan inte ställas in olika.','Some fields in "%s" have the same name as fields in other field groups. WPML stores translation preferences by field name, so fields that share a name cannot be set differently.'=>'Vissa fält i “%s” har samma namn som fält i andra fältgrupper. WPML sparar översättningsval per fältnamn, så fält som delar namn kan inte ställas in olika.','What you set here may not be what your visitors get'=>'Det du ställer in här kanske inte är vad dina besökare ser','The field %1$s also exists in "%2$s". Rename this field to give it a translation setting of its own.'=>'Fältet %1$s finns även i “%2$s”. Byt namn på detta fält för att ge det en egen översättningsinställning.','See both fields'=>'Visa båda fälten','Go to Media Translation settings'=>'Gå till inställningar för medieöversättning','This content has ACF image, gallery, or file fields, but the alt text, caption, and title of their media will not be sent for translation. To include them, turn on "Translate Media Library texts when translating content" in WPML Media Translation settings.'=>'Detta innehåll har ACF-fält för bild, galleri eller fil, men alternativtext, bildtext och titel för dessa media kommer inte att skickas för översättning. För att inkludera dem, aktivera ”Översätt texter i mediebiblioteket när innehåll översätts” i inställningarna för WPML Media Translation.','Media texts are not being translated'=>'Medietexter översätts inte','%1$sGo to Media Translation settings%2$s'=>'%1$sGå till inställningar för medieöversättning%2$s','Translate this Options page from the <b>Translation Dashboard</b>'=>'Översätt denna alternativsida från <b>översikten för översättning</b>','You no longer need to switch the admin language to translate options manually. Translate all your options from the %1$sTranslation Dashboard%2$s.'=>'Du behöver inte längre byta administratörsspråk för att översätta alternativ manuellt. Översätt alla dina alternativ från %1$söversikten för översättning%2$s.','Go to the Translation Dashboard'=>'Gå till översikten för översättning','To change a finished translation, go to %1$sTranslation Jobs%2$s and click on the Edit Translation icon.'=>'För att ändra en slutförd översättning, gå till %1$sÖversättningsjobb%2$s och klicka på ikonen Redigera översättning.','Go to Translation Jobs'=>'Gå till översättningsjobb','WPML blocked this save to prevent data loss. The form sent about %1$s fields, but the PHP max_input_vars limit on this server (%2$s) let fewer through. Saving now would permanently delete the fields that did not arrive, including repeater rows. Nothing was saved. Ask your host to raise max_input_vars above %1$s and save again.'=>'WPML blockerade denna sparandeåtgärd för att förhindra dataförlust. Formuläret skickade cirka %1$s fält, men PHP-gränsen för max_input_vars på denna server tillät bara (%2$s). Att spara nu skulle permanent radera de fält som inte kom fram, inklusive repeterarrader. Ingenting sparades. Be ditt webbhotell att höja max_input_vars över %1$s och spara igen.','Save blocked to prevent data loss'=>'Sparande blockerat för att förhindra dataförlust','You need to %1$stranslate this post manually%2$s because the field groups attached to it use different translation options:'=>'Du behöver %1$söversätta detta inlägg manuellt%2$s eftersom fältgrupperna som är kopplade till det använder olika översättningsval:','and %d more.'=>'och %d till.','Show all field groups'=>'Visa alla fältgrupper','and %d more'=>'och %d till','You need to translate this post manually because the field groups attached to it use different translation options: %s.'=>'Du behöver översätta detta inlägg manuellt eftersom fältgrupperna som är kopplade till det använder olika översättningsval: %s.','Edit %s'=>'Redigera %s','Go to documentation'=>'Gå till dokumentationen','This field value is copied from the default language and will be kept in sync across languages.'=>'Detta fältvärde kopieras från källspråket och kommer att hållas synkroniserat mellan språk.','Synchronise translations'=>'Synkronisera översättningar','Keep repeater and flexible sub-fields in the same order as the default language.'=>'Håll underfält för repeterare och flexibelt innehåll i samma ordning som på källspråket.','ACFML Synchronise translations'=>'ACFML Synkronisera översättningar','Translate ACF Local JSON and PHP-Registered Fields'=>'Översätt lokala ACF-fält registrerade via JSON och PHP','ACF allows you to %1$sregister fields via PHP%2$s or %3$ssave field settings as JSON files%4$s. You can also save post types, taxonomies, or options pages settings to JSON files.'=>'ACF låter dig %1$sregistrera fält via PHP%2$s eller %3$sspara fältinställningar som JSON-filer%4$s. Du kan även spara inställningar för inläggstyper, taxonomier eller alternativsidor till JSON-filer.','Configure how ACF Multilingual handles translations for these items.'=>'Konfigurera hur ACF Multilingual hanterar översättningar för dessa objekt.','Sync <b>Translation Preferences</b> for Local Fields'=>'Synkronisera <b>översättningsval</b> för lokala fält','Don’t sync translation preferences'=>'Synkronisera inte översättningsval','Sync once now'=>'Synkronisera en gång nu','Sync on every request (may affect performance)'=>'Synkronisera vid varje anrop (kan påverka prestandan)','Register Labels for Translation'=>'Registrera etiketter för översättning','Scans post types, taxonomies, options pages, and field groups stored in the "acf-json" directory, then registers their labels with WPML so you can translate them.'=>'Söker igenom inläggstyper, taxonomier, alternativsidor och fältgrupper som lagras i mappen “acf-json” och registrerar sedan deras etiketter i WPML så att du kan översätta dem.','Don’t register labels'=>'Registrera inte etiketter','Register labels now'=>'Registrera etiketter nu','Apply'=>'Verkställ','The synchronization of translation preferences is disabled.'=>'Synkroniseringen av översättningsval är inaktiverad.','Translation preferences synchronized.'=>'Översättningsval har synkroniserats.','The synchronization of translation preferences is enabled.'=>'Synkroniseringen av översättningsval är aktiverad.','%s group'=>'%s grupp' . "\0" . '%s grupper','%s post type'=>'%s inläggstyp' . "\0" . '%s inläggstyper','%s taxonomy'=>'%s taxonomi' . "\0" . '%s taxonomier','%s options page'=>'%s alternativsida' . "\0" . '%s alternativsidor','No local field groups, post types, taxonomies, or Options pages were found.'=>'Inga lokala fältgrupper, inläggstyper, taxonomier eller alternativsidor hittades.','Used between elements of a two elements list and '=>' och ','Used before the last element of a three or more elements list, and '=>', och ','Successfully registered labels for %s.'=>'Registrerade etiketter för %s utan problem.','%1$sChange translation settings%2$s'=>'%1$sÄndra översättningsinställningar%2$s','%1$sTranslate labels%2$s'=>'%1$sÖversätt etiketter%2$s','Not translatable'=>'Inte översättningsbar','Translatable'=>'Översättningsbar','only show translated items'=>'visa endast översatta objekt','use translation if available or fallback to default language'=>'använd översättning om tillgänglig eller återgå till källspråket','This content must be translated manually due to the translation option you selected for the "%1$s" field group.'=>'Detta innehåll måste översättas manuellt på grund av det översättningsval du valt för fältgruppen “%1$s”.']];